common='''## Delivery contract
Build the application end to end in this workspace. Do not just describe a plan or return code snippets. Read this RFP and ENVIRONMENT.md, then implement, build and test as far as the provided environment permits. Use tools to create actual project files. You may discover available file,shell,Docdex,planning and testing tools. You may install public dependencies inside this workspace. No production deployment,external account creation,paid services or host administration is authorized. Keep secrets and personal host data out of the project.

One initial request is supplied; no further feature clarifications or evaluator fixes will be provided. Make reasonable product decisions and document them. Internal tool calls and self-corrections are allowed. Do not lower requirements to make tests pass. The common maximum is60minutes,100model calls,200tool calls,1million aggregate model tokens and8192output tokens per call, subject to64K context. Finish early only if the application is actually complete or you have accurately documented a blocker. Do not claim tests/builds you did not run.

Deliver source,dependency manifests and lockfiles,build configuration,tests,demo fixtures,and README. Include DELIVERY.md with implemented features,exact executed commands and results,known bugs,unverified checks,and missing requirements. Provide a machine-readable delivery.json with keys app,platform,buildCommand,runCommand,testCommand,artifactPaths,knownLimitations. Never include production secrets. Do not remove or rewrite RFP.md or ENVIRONMENT.md. No human will repair submitted code before scoring. Generated dependencies/build caches are excluded from source review but source and produced artifacts are preserved.

## Quality rubric (100points)
Features35: each of the35 numbered feature checks is worth1point. Build/delivery15,reliability/tests15,UI/UX15,code quality10,security10. Evaluation uses actual build/test/runtime evidence plus code review. An absent feature fails. An implemented but untestable native-platform behavior is marked unverified,not passed. Scores include verification coverage; environment gaps are disclosed separately. A screenshot/mockup alone does not prove behavior.
'''
common_rubric={
'build_delivery':(3,['Clean documented dependency install and build succeeds','Expected runnable distributable/project artifact exists and is valid','Documented start/install command launches correct application','README,DELIVERY.md and delivery.json are accurate and reproducible','No missing source/assets/configuration or placeholder runtime dependencies']),
'reliability_tests':(3,['Meaningful automated tests pass and assert domain behavior','At least one persistence/relaunch or save/load flow is verified','Invalid input/error path is handled without crash or data loss','Primary happy-path end-to-end flow completes','No blocking console/runtime errors in exercised flows']),
'ui_ux':(3,['Consistent readable hierarchy,spacing,color and typography','Navigation and primary actions are discoverable and complete','Responsive/safe-area layouts work at required screen sizes','Accessibility labels,keyboard or assistive navigation and contrast are adequate','Empty,loading,error,confirmation and saved-state feedback are usable']),
'code_quality':(2,['Clear separation of domain,state,persistence and presentation','Typed/domain models and meaningful names; no pervasive any or unsafe casts','Reasonable module boundaries and low avoidable duplication','Errors/resources handled explicitly; no blanket silent exception swallowing','Maintainable tests/configuration and no substantial TODO/stubbed core functionality'])}
cases=[];grades=[]
for idx,(platform,name,desc,groups,details,security) in enumerate(apps,1):
 ident=f'app-{idx:02}-{platform}';text=f'# RFP: {name}\n\nPlatform: {platform}\n\n{desc}\n\n'+common+'\n## Platform and data constraints\n'+details+'\n\n## Required features\n';criteria=[];n=0
 for group,checks in groups:
  text+='\n### '+group+'\n'
  for check in checks:
   n+=1;cid=f'F{n:02}';text+=f'- {cid}: {check}.\n';criteria.append(dict(id=cid,category='features',weight=1,requirement=check))
 text+='\n## Security requirements\n'
 for j,check in enumerate(security,1):text+=f'- S{j}: {check}.\n'
 text+='\n## Evaluation contract\nEvery visible control must perform its claimed action. Demo data must be fictional and deterministic. Tests must validate behavior,not merely assert that files exist. Native signing/store publication is not required. Describe all environment blockers accurately.\n'
 (root/'rfps'/f'{ident}.md').write_text(text)
 for cat,(weight,checks) in common_rubric.items():
  for j,c in enumerate(checks,1):criteria.append(dict(id=f'{cat}-{j}',category=cat,weight=weight,requirement=c))
 for j,c in enumerate(security,1):criteria.append(dict(id=f'security-{j}',category='security',weight=2,requirement=c))
 assert sum(c['weight'] for c in criteria)==100 and len(criteria)==60
 fixture={'RFP.md':dict(encoding='utf8',content=text,sha256=hashlib.sha256(text.encode()).hexdigest())}
 prompt=f'Build {name}, the complete {platform} application described in RFP.md, end to end in this workspace. Read RFP.md and ENVIRONMENT.md first. Implement the full product,run the available builds/tests,and deliver the actual project and artifacts. Do not stop at a plan or code snippets. No follow-up instructions will be supplied. Use the permitted tools and document any genuine environment blocker honestly.'
 cases.append(dict(id=ident,domain=platform,family=ident,split='development',variant=idx,prompt=prompt,history=[],files=fixture,execution=dict(effort='low',deadlineMs=3600000,writes=True,web=True,media=False),comparison='implementation'))
 grades.append(dict(id=ident,name=name,platform=platform,criteria=criteria,scoring='pass=full weight,partial=half weight only with explicit evidence,fail=0,unverified=0 demonstrated points and excluded from assessed-only denominator; record coverage. Missing implementation is fail,not unverified. UI visual judgments need screenshots or explicit source-only limitation.'))
for name,data in [('prompts.jsonl',cases),('grading.jsonl',grades)]: (root/name).write_text(''.join(json.dumps(x)+'\n' for x in data))
manifest=dict(schemaVersion=1,protocol='trust-workflows-v1',caseCount=5,createdAt=datetime.datetime.now(datetime.timezone.utc).isoformat(),promptsSha256=hashlib.sha256((root/'prompts.jsonl').read_bytes()).hexdigest(),gradingSha256=hashlib.sha256((root/'grading.jsonl').read_bytes()).hexdigest(),limitations=['Raw baseline is a native tool loop,not a single text completion.','One first attempt per arm/job; no evaluator code repairs.','Native iOS execution requires external Mac/Xcode; otherwise mark unverified.','Source and UX review include documented reviewer judgment,not universal intelligence measurement.'])
(root/'manifest.json').write_text(json.dumps(manifest,indent=2)+'\n');print(json.dumps(manifest))
